tool_input.command:
mkdir -p .tmp/seqprobe && cat > .tmp/seqprobe/main.go <<'EOF'
package main

import (
	"fmt"
	"gopkg.in/yaml.v3"
)

func walk(n *yaml.Node, path string) {
	if n == nil {
		return
	}
	kinds := map[yaml.Kind]string{yaml.DocumentNode: "doc", yaml.SequenceNode: "seq", yaml.MappingNode: "map", yaml.ScalarNode: "scalar", yaml.AliasNode: "alias"}
	fmt.Printf("%-22s kind=%-7s tag=%-8s value=%q line=%q head=%q\n", path, kinds[n.Kind], n.Tag, n.Value, n.LineComment, n.HeadComment)
	for i, c := range n.Content {
		walk(c, fmt.Sprintf("%s/%d", path, i))
	}
}

func main() {
	src := "write_set:\n  - # placeholder\nfiles:\n  - a.go # note\n"
	var doc yaml.Node
	if err := yaml.Unmarshal([]byte(src), &doc); err != nil {
		panic(err)
	}
	walk(&doc, "")
}
EOF
cd <repo>/.tmp/seqprobe && go mod init probe 2>/dev/null; go mod edit -require=gopkg.in/yaml.v3@v3.0.1 && go mod tidy 2>&1 | tail -1 && go run . 2>&1 | head -20
